<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {scheduleApi} from '../schedules'
type Year={id:number;name:string;start_date:string;end_date:string}
type Class={id:number;year_id:number;grade_label:string;name:string;is_active:number}
const props=defineProps<{years:Year[];classes:Class[];revision:number;initialYearId:number}>()
const emit=defineEmits<{busy:[value:boolean];saved:[]}>()
const source=ref(props.initialYearId),target=ref(0),mapping=ref<Record<number,number>>({}),preview=ref<any>(null),selected=ref<number[]>([]),confirmed=ref(false),busy=ref(false),error=ref(''),message=ref('')
const sourceYear=computed(()=>props.years.find(y=>y.id===source.value)),targetYear=computed(()=>props.years.find(y=>y.id===target.value))
const sourceClasses=computed(()=>props.classes.filter(c=>c.year_id===source.value)),destinations=computed(()=>props.classes.filter(c=>c.year_id===target.value&&c.is_active))
const laterYears=computed(()=>props.years.filter(y=>sourceYear.value&&y.start_date>sourceYear.value.end_date))
const ready=computed(()=>preview.value?.students.filter((s:any)=>s.status==='ready')??[])
const classLabel=(id:number)=>{const c=props.classes.find(c=>c.id===id);return c?'Grade '+c.grade_label+(c.name?' · Class '+c.name:''):'Unknown class'}
function invalidate(){preview.value=null;selected.value=[];confirmed.value=false;error.value=''}
watch(source,()=>{target.value=0;mapping.value={}})
watch(target,()=>mapping.value={})
watch([source,target,mapping,()=>props.revision],invalidate,{deep:true})
function payload(){return {source_year_id:source.value,target_year_id:target.value,revision:props.revision,mappings:Object.entries(mapping.value).filter(([,id])=>id>0).map(([id,to])=>({source_class_id:Number(id),target_class_id:to}))}}
async function check(){busy.value=true;emit('busy',true);error.value='';message.value='';preview.value=null;confirmed.value=false;try{preview.value=await scheduleApi('admin/school/rollover/preview','POST',payload());selected.value=ready.value.map((s:any)=>s.student_user_id)}catch(e){error.value=e instanceof Error?e.message:'Unable to preview rollover.'}finally{busy.value=false;emit('busy',false)}}
async function save(){if(!confirmed.value||!selected.value.length||!preview.value)return;busy.value=true;emit('busy',true);error.value='';try{const r=await scheduleApi('admin/school/rollover','POST',{...payload(),student_ids:selected.value,digest:preview.value.digest,confirmed:true});message.value=r.message;invalidate();emit('saved')}catch(e){error.value=e instanceof Error?e.message:'Unable to save rollover.';confirmed.value=false}finally{busy.value=false;emit('busy',false)}}
</script>
<template><details class="rollover"><summary>Academic year rollover</summary><p>Move selected students into the next academic year. Create the destination year and its classes above first.</p><p class="rollover-help">Previous attendance, homework, notices, enrollment history, login IDs and parent links are preserved. Set up the new year’s subjects, timetable and rooms separately.</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><fieldset :disabled="busy"><div class="rollover-fields"><label>From academic year<select v-model.number="source"><option :value="0" disabled>Choose a year</option><option v-for="y in years" :key="y.id" :value="y.id">{{y.name}}</option></select></label><label>To academic year<select v-model.number="target"><option :value="0" disabled>Choose a later year</option><option v-for="y in laterYears" :key="y.id" :value="y.id">{{y.name}}</option></select></label></div><p v-if="source&&!laterYears.length" class="rollover-help">Create a later academic year before continuing.</p><template v-if="targetYear"><p>New enrollment starts <strong>{{targetYear.start_date}}</strong>.</p><p class="rollover-help">Choose a destination for each class you want to move. Leave graduating classes unchanged, or select the same grade in the new year for students repeating a grade.</p><div v-for="c in sourceClasses" :key="c.id" class="rollover-mapping"><span>{{classLabel(c.id)}}</span><label><span class="sr-only">Destination for {{classLabel(c.id)}}</span><select :value="mapping[c.id]??0" @change="mapping[c.id]=Number(($event.target as HTMLSelectElement).value)"><option :value="0">Leave unchanged</option><option v-for="dest in destinations" :key="dest.id" :value="dest.id">{{classLabel(dest.id)}}</option></select></label></div><p v-if="!destinations.length" class="rollover-help">Create active classes in the destination year first.</p><button type="button" :disabled="!Object.values(mapping).some(Boolean)" @click="check">{{busy?'Checking…':'Preview students'}}</button></template><template v-if="preview"><h3>Review {{preview.students.length}} students</h3><p class="rollover-help">Includes enabled students enrolled in the mapped classes on {{preview.source.end_date}}. Students already enrolled in the new year or with conflicting records cannot be selected. Unselected students remain unchanged.</p><div class="rollover-selection"><strong>{{selected.length}} selected</strong><button type="button" class="secondary" @click="selected=ready.map((s:any)=>s.student_user_id)">Select all ready</button><button type="button" class="secondary" @click="selected=[]">Clear</button></div><div class="rollover-students"><label v-for="s in preview.students" :key="s.membership_id" class="rollover-student"><input v-model="selected" type="checkbox" :value="s.student_user_id" :disabled="s.status!=='ready'"><span><strong>{{s.full_name}}</strong><small>{{s.login_id}} — {{classLabel(s.class_id)}} → {{classLabel(s.target_class_id)}}</small><small v-if="s.status!=='ready'">{{s.status==='already_enrolled'?'Already enrolled — no duplicate will be created':'Conflicting enrollment — review this student individually'}}</small></span></label></div><p v-if="!preview.students.length">No eligible students were found for these class mappings.</p><label class="rollover-confirm"><input v-model="confirmed" type="checkbox">I reviewed the selected students, destination classes and start date.</label><button type="button" :disabled="!confirmed||!selected.length" @click="save">{{busy?'Saving…':'Confirm rollover for '+selected.length+' students'}}</button></template></fieldset></details></template>
<style scoped>.rollover{margin-top:20px;padding:22px;background:#fff;border:1px solid #dce5df;border-radius:12px}.rollover summary{cursor:pointer;font-size:18px;font-weight:600;min-height:32px}.rollover p{font-size:14px;line-height:1.6}.rollover .rollover-help{font-size:12px;color:#60736e}.rollover fieldset{border:0;padding:0;min-width:0}.rollover-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.rollover label{font-size:13px;margin:10px 0}.rollover select{width:100%;padding:10px;font:inherit;font-size:16px;min-height:44px;border:1px solid #bccfc5;border-radius:8px;background:white;color:#243e33}.rollover-mapping{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:16px;border-bottom:1px solid #dce5df;font-size:14px}.rollover button{width:auto;margin:12px 8px 0 0;font-size:14px;padding:12px;min-height:44px}.rollover-selection{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:14px}.rollover-selection button{margin:0}.rollover-students{max-height:420px;overflow:auto;margin:16px 0;border-block:1px solid #dce5df}.rollover .rollover-student,.rollover .rollover-confirm{display:flex;align-items:start;gap:10px;padding:10px 0}.rollover input[type=checkbox]{width:20px;height:20px;min-width:20px;margin:0}.rollover small{display:block;font-size:12px;margin-top:5px;color:#60736e;line-height:1.5}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.rollover :is(button,select,input,summary):focus-visible{outline:2px solid #21896f;outline-offset:2px}@media(max-width:550px){.rollover{padding:16px}.rollover-fields,.rollover-mapping{grid-template-columns:1fr;gap:4px}.rollover-mapping{padding-top:12px}.rollover button{max-width:100%}}</style>
